package com.example.workout.workout.service; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*; import com.example.workout.common.exception.AppException; import com.example.workout.workout.entity.WorkoutEntity; import com.example.workout.workout.model.*; import com.example.workout.workout.repository.WorkoutRepository; import java.time.LocalDate; import java.util.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; @ExtendWith(MockitoExtension.class) class WorkoutServiceImplTest { @Mock WorkoutRepository repository; @InjectMocks WorkoutServiceImpl service; @Test void get_missing_workout_ko(){when(repository.findById(99L)).thenReturn(Optional.empty());assertThatThrownBy(()->service.get(99L)).isInstanceOf(AppException.class);} @Test void create_workout_ok(){var workout=Workout.builder().withWorkoutDate(LocalDate.of(2026,9,20)).withWorkoutType(WorkoutType.LONG_RUN).withCompleted(true).withSource(WorkoutSource.MANUAL).build();var saved=new WorkoutEntity();saved.setId(1L);saved.setWorkoutDate(workout.getWorkoutDate());saved.setWorkoutType(workout.getWorkoutType());saved.setCompleted(true);saved.setSource(WorkoutSource.MANUAL);saved.setCreatedAt(java.time.OffsetDateTime.now());saved.setUpdatedAt(saved.getCreatedAt());when(repository.save(any(WorkoutEntity.class))).thenReturn(saved);var result=service.create(workout);assertThat(result.getId()).isEqualTo(1L);verify(repository).save(any(WorkoutEntity.class));} @Test void duplicate_segment_positions_ko(){var workout=Workout.builder().withWorkoutDate(LocalDate.now()).withWorkoutType(WorkoutType.INTERVALS).withCompleted(true).withSource(WorkoutSource.MANUAL).withSegments(new ArrayList<>(List.of(WorkoutSegment.builder().withPosition(1).withSegmentType(WorkoutSegmentType.INTERVAL).build(),WorkoutSegment.builder().withPosition(1).withSegmentType(WorkoutSegmentType.RECOVERY).build()))).build();assertThatThrownBy(()->service.create(workout)).isInstanceOf(AppException.class);verify(repository,never()).save(any(WorkoutEntity.class));} }
